from docx import Document
import subprocess, re
from pathlib import Path
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.shared import Pt
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

DOC='/mnt/data/DG-202611_正式方案书整合预览_v0.3.1.docx'
PDF='/mnt/data/dg202611_render2/DG-202611_正式方案书整合预览_v0.3.1.pdf'

def norm(s):
    s=s.replace('–','-').replace('—','-').replace('−','-')
    return re.sub(r'\s+','',s)

# Load all body page text from page 5 onward.
pages={}
for n in range(5,65):
    r=subprocess.run(['pdftotext','-f',str(n),'-l',str(n),'-layout',PDF,'-'],capture_output=True,text=True)
    pages[n]=norm(r.stdout)

doc=Document(DOC)
toc=doc.tables[0]
miss=[]
found={}
for row in toc.rows:
    heading=row.cells[0].text.strip()
    nh=norm(heading)
    page=None
    for n, txt in pages.items():
        if nh in txt:
            page=n; break
    if page is None:
        # Fallback: use numbered prefix + first meaningful 10 chars.
        m=re.match(r'^(\d+(?:\.\d+)*|第\d+章)\s*(.*)$',heading)
        if m:
            key=norm(m.group(1)+m.group(2)[:12])
        else:
            key=nh[:16]
        for n,txt in pages.items():
            if key and key in txt:
                page=n; break
    if page is None:
        miss.append(heading)
        row.cells[1].text=''
    else:
        found[heading]=page
        p=row.cells[1].paragraphs[0]
        p.text=str(page)
        p.alignment=WD_ALIGN_PARAGRAPH.RIGHT
        p.paragraph_format.space_after=Pt(0.5)
        for run in p.runs:
            run.font.name='Times New Roman'; run.font.size=Pt(8.7)
            rPr=run._element.get_or_add_rPr(); rFonts=rPr.rFonts
            if rFonts is None:
                rFonts=OxmlElement('w:rFonts'); rPr.insert(0,rFonts)
            rFonts.set(qn('w:eastAsia'),'Noto Serif CJK SC')
            rFonts.set(qn('w:ascii'),'Times New Roman'); rFonts.set(qn('w:hAnsi'),'Times New Roman')

doc.save(DOC)
print('found',len(found),'miss',len(miss))
if miss:
    print('MISSES:')
    for x in miss: print(x)
PY
